per_case_results.actual_sql:
SELECT 
    (COUNT(CASE WHEN "gender" = 'F' AND "birth_date" > '1930-12-31' THEN 1 END) * 100.0 / COUNT(*)) AS percentage
FROM "patients";

SELECT COUNT(*) 
FROM "patients" 
WHERE "gender" = 'F' AND "diagnosis" = 'APS';

SELECT COUNT(*) 
FROM "patients" 
WHERE "ig_g" > 1000;
